define(['core/ajax','core/log'],function(Ajax,Log){var player=null;var config=null;var HEARTBEAT_INTERVAL=30;var state={sessionid:null,playing:false,segmentstart:null,wallclockstart:null,lasttime:0,duration:0,playbackrate:1,heartbeatid:null,lastHeartbeatWallclock:0,seekblocked:false,currentReplayEnd:null,isProgrammaticSeek:false,}; function uuid(){if(window.crypto&&window.crypto.randomUUID){return window.crypto.randomUUID().replace(/-/g,'');}return 'sess'+Date.now()+Math.random().toString(36).substring(2,12);}function ajax(methodname,args){return Ajax.call([{methodname:methodname,args:args}])[0];}function saveSegment(start,end,reason){if(end<=start){return;}var now=Math.floor(Date.now()/1000);return ajax('mod_videotrack_save_segment',{cmid:config.cmid,sessionid:state.sessionid,videotimestart:Math.round(start*1000)/1000,videotimeend:Math.round(end*1000)/1000,wallclockstart:state.wallclockstart||now,wallclockend:now,playbackrate:state.playbackrate||1,endreason:reason,durationseconds:state.duration,}).then(updateProgress).catch(Log.debug);}function saveCurrentProgress(reason){if(!state.playing||state.segmentstart===null){return Promise.resolve(null);}var end=getCurrentVideoTime();if(end<=state.segmentstart){if(reason==='reaction'||reason==='note'){end=state.segmentstart+0.25;if(state.duration&&state.duration>0){end=Math.min(end,state.duration);}}if(end<=state.segmentstart){return Promise.resolve(null);}}return saveSegment(state.segmentstart,end,reason||'interaction');}function updateProgress(response){if(!response){return response;}var pct=document.getElementById('videotrack-progress-percent');if(pct){pct.textContent=parseFloat(response.completionpercent||0).toFixed(1)+'%';}var sec=document.getElementById('videotrack-covered-seconds');if(sec){sec.textContent=formatSeconds(response.uniquecoveredseconds||0);} if(typeof response.uniquereactions!=='undefined'){var counter=document.getElementById('videotrack-unique-reactions');if(counter){counter.textContent=response.uniquereactions;}} if(response.intervaljson){updateIntervalBar(response.intervaljson,response.durationseconds||state.duration);}return response;}function formatSeconds(s){s=Math.floor(s);var h=Math.floor(s/3600);var m=Math.floor((s%3600)/60);var sec=s%60;if(h>0){return h+':'+pad(m)+':'+pad(sec);}return pad(m)+':'+pad(sec);}function pad(n){return n<10?'0'+n:''+n;} function startSegment(currentTime){state.playing=true;state.segmentstart=currentTime;state.wallclockstart=Math.floor(Date.now()/1000);state.lastHeartbeatWallclock=state.wallclockstart;state.lasttime=currentTime;}function closeSegment(reason){if(!state.playing||state.segmentstart===null){return;}player.getCurrentTime().then(function(t){saveSegment(state.segmentstart,t,reason);state.playing=false;state.segmentstart=null;});} function startHeartbeat(){if(state.heartbeatid){return;}state.heartbeatid=window.setInterval(function(){if(!state.playing||state.segmentstart===null){return;}var now=Math.floor(Date.now()/1000);if(now-state.lastHeartbeatWallclock>=HEARTBEAT_INTERVAL){player.getCurrentTime().then(function(t){saveSegment(state.segmentstart,t,'heartbeat');state.segmentstart=t;state.wallclockstart=now;state.lastHeartbeatWallclock=now;});}},2000);}function stopHeartbeat(){if(state.heartbeatid){window.clearInterval(state.heartbeatid);state.heartbeatid=null;}} function showResumeNotice(seconds){var existing=document.getElementById('videotrack-resume-notice');if(existing){existing.parentNode.removeChild(existing);}var formatted=formatSeconds(seconds);var notice=document.createElement('div');notice.id='videotrack-resume-notice';notice.className='videotrack-resume-notice alert alert-info alert-dismissible mt-1';notice.setAttribute('role','status');notice.setAttribute('aria-live','polite');var text=document.createElement('span');text.textContent=(config.resumedlabel||'Resumed from')+' '+formatted+'.';notice.appendChild(text);var btn=document.createElement('button');btn.type='button';btn.className='btn-close ms-2';btn.setAttribute('aria-label',config.dismisslabel||'Dismiss');btn.addEventListener('click',function(){notice.parentNode.removeChild(notice);});notice.appendChild(btn);var shell=document.querySelector('.videotrack-player-shell');if(shell){shell.insertBefore(notice,shell.firstChild);}window.setTimeout(function(){if(notice.parentNode){notice.parentNode.removeChild(notice);}},6000);} function updateIntervalBar(intervaljson,duration){var canvas=document.getElementById('videotrack-interval-bar');if(!canvas||!duration){return;}try{var intervals=JSON.parse(intervaljson);var ctx=canvas.getContext('2d');var w=canvas.offsetWidth||canvas.width;var h=canvas.height;canvas.width=w;ctx.clearRect(0,0,w,h);ctx.fillStyle='#e9ecef';ctx.fillRect(0,0,w,h);ctx.fillStyle='#28a745';var covered=0;intervals.forEach(function(seg){var x1=Math.round((seg[0]/duration)*w);var x2=Math.round((seg[1]/duration)*w);ctx.fillRect(x1,0,Math.max(2,x2-x1),h);covered+=Math.max(0,seg[1]-seg[0]);});var pct=duration>0?Math.min(100,Math.round((covered/duration)*100)):0;var baseLabel=canvas.getAttribute('title')||'';canvas.setAttribute('aria-label',baseLabel+' — '+pct+'%');}catch(e){}}function installGlobalListeners(){document.addEventListener('visibilitychange',function(){if(document.hidden&&state.playing){closeSegment('tab');setReactionButtons(false);}});window.addEventListener('pagehide',function(){if(state.playing){closeSegment('pagehide');}}); window.addEventListener('beforeunload',function(){if(!state.playing||state.segmentstart===null){return;}var start=state.segmentstart;var end=state.lasttime;if(end<=start){return;}var now=Math.floor(Date.now()/1000);var beaconUrl=config.beaconurl||'';if(navigator.sendBeacon&&beaconUrl){navigator.sendBeacon(beaconUrl,new Blob([JSON.stringify([{methodname:'mod_videotrack_save_segment',args:{cmid:config.cmid,sessionid:state.sessionid,videotimestart:start,videotimeend:end,wallclockstart:state.wallclockstart||now,wallclockend:now,playbackrate:state.playbackrate||1,endreason:'beforeunload',durationseconds:state.duration||0,}}])],{type:'application/json'}));}});} function loadVimeoSDK(callback){if(window.Vimeo&&window.Vimeo.Player){callback();return;}var script=document.createElement('script');script.src='https://player.vimeo.com/api/player.js';script.async=true; script.crossOrigin='anonymous';script.onload=callback;script.onerror=function(){Log.error('mod_videotrack: failed to load Vimeo Player SDK from player.vimeo.com'); var wrap=document.getElementById('mod-videotrack-player');if(wrap){var notice=document.createElement('div');notice.className='alert alert-warning mt-2';notice.setAttribute('role','alert');notice.textContent=config.sdkerrorlabel||'The video player could not be loaded. '+'This may be caused by an ad-blocker or network restriction. '+'Please disable any content blockers and reload the page.';wrap.parentNode.insertBefore(notice,wrap.nextSibling);}};document.head.appendChild(script);}function buildPlayer(){var container=document.getElementById('mod-videotrack-player');if(!container){return;}player=new window.Vimeo.Player(container,{id:config.videoid,responsive:true,controls:config.showcontrols!==false,autoplay:!!config.autoplay,loop:!!config.loop,muted:!!(config.autoplay||config.startmuted),fullscreen:config.showfullscreen!==false,speed:true, playsinline:true,dnt:true,}); if(config.playbackspeeds&&config.playbackspeeds.length){ var defaultspeed=config.playbackspeeds.indexOf(1)>=0?1:config.playbackspeeds[Math.floor(config.playbackspeeds.length/2)];player.setPlaybackRate(defaultspeed).catch(Log.debug);}player.getDuration().then(function(d){state.duration=d; if(typeof config.resumeposition==='number'&&config.resumeposition>2){state.isProgrammaticSeek=true;player.setCurrentTime(config.resumeposition).then(function(){state.isProgrammaticSeek=false;showResumeNotice(config.resumeposition);}).catch(function(){ state.isProgrammaticSeek=false;state._pendingResume=config.resumeposition;});} if(config.maxplaybackrate>0){var maxRateLoad=config.maxplaybackrate/100;player.getPlaybackRate().then(function(currentRate){if(currentRate>maxRateLoad){player.setPlaybackRate(maxRateLoad).catch(Log.debug);}}).catch(Log.debug);}}); if(config.captions&&config.captionslang){player.enableTextTrack(config.captionslang).catch(function(){});} buildVimeoSkipButtons();player.on('play',function(data){player.getCurrentTime().then(function(t){ if(state._pendingResume&&state._pendingResume>2){var resumePos=state._pendingResume;state._pendingResume=null;state.isProgrammaticSeek=true;player.setCurrentTime(resumePos).then(function(){state.isProgrammaticSeek=false;showResumeNotice(resumePos);}).catch(function(){state.isProgrammaticSeek=false;});return;}startSegment(t);startHeartbeat();setReactionButtons(true); if(config.maxplaybackrate>0){var maxRatePlay=config.maxplaybackrate/100;player.getPlaybackRate().then(function(rate){if(rate>maxRatePlay){player.setPlaybackRate(maxRatePlay).catch(Log.debug);}}).catch(Log.debug);}});});player.on('pause',function(data){stopHeartbeat();closeSegment('pause');setReactionButtons(false);});player.on('ended',function(){stopHeartbeat();closeSegment('ended');setReactionButtons(false);});player.on('seeked',function(data){ if(state.seekblocked||state.isProgrammaticSeek){return;}var newtime=data.seconds;var oldtime=state.lasttime;if(state.playing){if(!config.allowseekforward&&newtime>oldtime){state.seekblocked=true;window.setTimeout(function(){state.seekblocked=false;},600);state.isProgrammaticSeek=true;player.setCurrentTime(oldtime).then(function(){state.isProgrammaticSeek=false;});return;}if(!config.allowseekbackward&&newtime<oldtime){state.seekblocked=true;window.setTimeout(function(){state.seekblocked=false;},600);state.isProgrammaticSeek=true;player.setCurrentTime(oldtime).then(function(){state.isProgrammaticSeek=false;});return;} saveSegment(state.segmentstart,oldtime,'seek');startSegment(newtime);}});player.on('timeupdate',function(data){state.lasttime=data.seconds;state.playbackrate=data.playbackRate||1; if(state.currentReplayEnd!==null&&data.seconds>=state.currentReplayEnd){player.pause();state.currentReplayEnd=null;}}); document.addEventListener('click',function(e){var btn=e.target.closest('.videotrack-replay');if(btn&&player){var start=parseFloat(btn.dataset.start)||0;var end=parseFloat(btn.dataset.end)||0;state.currentReplayEnd=end>0?end:null; state.isProgrammaticSeek=true;player.setCurrentTime(start).then(function(){state.isProgrammaticSeek=false;player.play();}).catch(function(){state.isProgrammaticSeek=false;});}});} function buildVimeoSkipButtons(){var showRewind=(config.rewindstep>0)&&(config.allowseekbackward!==false);var showFF=(config.fastforwardstep>0)&&(config.allowseekforward!==false);if(!showRewind&&!showFF){return;}var container=document.getElementById('mod-videotrack-player');if(!container){return;}var wrap=container.closest('.videotrack-player-wrap')||container.parentElement;var bar=document.createElement('div');bar.className='videotrack-skip-bar';if(showRewind){var rwBtn=document.createElement('button');rwBtn.type='button';rwBtn.className='btn btn-sm btn-dark videotrack-skip-btn';var rwIcon=document.createElement('span');rwIcon.setAttribute('aria-hidden','true');rwIcon.textContent='⏪ ';rwBtn.appendChild(rwIcon);rwBtn.appendChild(document.createTextNode(config.rewindstep+'s'));rwBtn.setAttribute('aria-label',(config.rewindlabel||'Rewind')+' '+config.rewindstep+' '+(config.secondslabel||'seconds'));rwBtn.addEventListener('click',function(){player.getCurrentTime().then(function(t){player.setCurrentTime(Math.max(0,t-config.rewindstep));});});bar.appendChild(rwBtn);}if(showFF){var ffBtn=document.createElement('button');ffBtn.type='button';ffBtn.className='btn btn-sm btn-dark videotrack-skip-btn';ffBtn.appendChild(document.createTextNode(config.fastforwardstep+'s '));var ffIcon=document.createElement('span');ffIcon.setAttribute('aria-hidden','true');ffIcon.textContent='⏩';ffBtn.appendChild(ffIcon);ffBtn.setAttribute('aria-label',(config.fastforwardlabel||'Fast-forward')+' '+config.fastforwardstep+' '+(config.secondslabel||'seconds'));ffBtn.addEventListener('click',function(){player.getCurrentTime().then(function(t){player.setCurrentTime(Math.min(state.duration||1e9,t+config.fastforwardstep));});});bar.appendChild(ffBtn);}wrap.appendChild(bar);} function setReactionButtons(playing){document.dispatchEvent(new CustomEvent('videotrack:playstate',{detail:{playing:playing}}));document.querySelectorAll('.videotrack-reaction-btn').forEach(function(btn){btn.disabled=!playing;btn.setAttribute('aria-disabled',playing?'false':'true');if(playing){btn.removeAttribute('tabindex');}else{btn.setAttribute('tabindex','-1');}btn.classList.toggle('videotrack-reaction-disabled',!playing);});}function announceReactionUnavailable(){var hint=document.getElementById('videotrack-reactions-hint');if(hint){hint.setAttribute('aria-live','polite');hint.classList.add('videotrack-reactions-hint-active');window.setTimeout(function(){hint.classList.remove('videotrack-reactions-hint-active');},1500);}} function installReactionHandler(){function showStatusMessage(message,isError){var id='videotrack-status-msg';var el=document.getElementById(id);if(!el){el=document.createElement('div');el.id=id;el.className='sr-only';el.setAttribute('aria-atomic','true');var shell=document.querySelector('.videotrack-player-shell');if(shell){shell.appendChild(el);}}el.setAttribute('role',isError?'alert':'status');el.textContent=message;window.setTimeout(function(){el.textContent='';},4000);}function appendReactionRow(eventid,reaction,videotime){var tbody=document.getElementById('videotrack-my-reactions');if(!tbody){return;} var placeholder=tbody.querySelector('.videotrack-no-reactions-placeholder');if(placeholder){placeholder.parentNode.removeChild(placeholder);}var tr=document.createElement('tr');tr.setAttribute('data-eventid',eventid); var tdtime=document.createElement('td');tdtime.textContent=formatSeconds(videotime);tr.appendChild(tdtime); var tdicon=document.createElement('td');var span=document.createElement('span');span.className='videotrack-report-icon';appendIconSafe(span,reaction.iconhtml);tdicon.appendChild(span);tr.appendChild(tdicon); var tddesc=document.createElement('td');tddesc.textContent=reaction.description||'';tr.appendChild(tddesc); var tdreplay=document.createElement('td');var replaybtn=document.createElement('button');replaybtn.type='button';replaybtn.className='btn btn-secondary btn-sm videotrack-replay';replaybtn.textContent=config.replaylabel||'Replay';replaybtn.setAttribute('aria-label',(config.replaylabel||'Replay')+' — '+formatSeconds(videotime));replaybtn.dataset.start=Math.max(0,videotime-30);replaybtn.dataset.end=videotime+30;tdreplay.appendChild(replaybtn);tr.appendChild(tdreplay); var tddel=document.createElement('td');var delbtn=document.createElement('button');delbtn.type='button';delbtn.className='btn btn-link btn-sm videotrack-delete-reaction';delbtn.textContent=config.removelabel||'Remove';delbtn.setAttribute('data-eventid',eventid); delbtn.setAttribute('aria-label',(config.removelabel||'Remove')+' — '+(reaction.label||'')+' — '+formatSeconds(videotime));tddel.appendChild(delbtn);tr.appendChild(tddel);tbody.appendChild(tr);}document.addEventListener('click',function(e){var reactionbtn=e.target.closest('.videotrack-reaction-btn');if(reactionbtn&&reactionbtn.getAttribute('aria-disabled')==='true'){announceReactionUnavailable();return;}if(reactionbtn){var currentTime=state.lasttime||0;reactionbtn.classList.add('videotrack-saving');saveCurrentProgress('reaction').then(function(){return ajax('mod_videotrack_save_reaction',{cmid:config.cmid,sessionid:state.sessionid,reactionid:parseInt(reactionbtn.getAttribute('data-reactionid'),10),videotime:currentTime,playbackrate:state.playbackrate||1,});}).then(function(response){reactionbtn.classList.remove('videotrack-saving');if(response&&response.reactioneventid){appendReactionRow(response.reactioneventid,{label:reactionbtn.getAttribute('data-reactionlabel'),description:reactionbtn.getAttribute('data-reactiondesc')||'',iconhtml:reactionbtn.getAttribute('data-reactioniconhtml')||'',},currentTime);}}).catch(function(err){reactionbtn.classList.remove('videotrack-saving');var msg=(err&&err.message)?err.message:(config.reactionerrorlabel||'Could not save reaction.');showStatusMessage(msg,true);});return;}var deletebtn=e.target.closest('.videotrack-delete-reaction');if(deletebtn){var row=deletebtn.closest('tr');var tbody=document.getElementById('videotrack-my-reactions');var rows=tbody?Array.from(tbody.querySelectorAll('tr[data-eventid]')):[];var idx=rows.indexOf(row);ajax('mod_videotrack_delete_reaction',{cmid:config.cmid,reactioneventid:parseInt(deletebtn.getAttribute('data-eventid'),10),}).then(updateProgress).then(function(response){if(response&&response.deleted){if(row){row.remove();}var remaining=tbody?Array.from(tbody.querySelectorAll('tr[data-eventid]')):[];if(remaining.length>0){var target=remaining[Math.min(idx,remaining.length-1)];var focusBtn=target.querySelector('button');if(focusBtn){focusBtn.focus();}}else if(tbody){tbody.setAttribute('tabindex','-1');tbody.focus();tbody.removeAttribute('tabindex');}}}).catch(Log.debug);}});} function appendIconSafe(target,iconhtml){if(!iconhtml){return;}var ALLOWED_TAGS={'IMG':true,'I':true,'SPAN':true};var ALLOWED_ATTRS={'class':true,'src':true,'alt':true,'aria-hidden':true};function isSafeIconSrc(value){if(!value){return false;}var trimmed=String(value).trim();var lower=trimmed.toLowerCase();if(lower.indexOf('javascript:')===0||lower.indexOf('data:')===0||lower.indexOf('vbscript:')===0){return false;}try{var url=new URL(trimmed,window.location.origin);if(url.origin!==window.location.origin){return false;}return url.pathname.indexOf('/pluginfile.php/')!==-1||url.pathname.indexOf('/webservice/pluginfile.php/')!==-1;}catch(e){return false;}}function sanitizeNode(node){if(node.nodeType===Node.TEXT_NODE){return document.createTextNode(node.textContent);}if(node.nodeType!==Node.ELEMENT_NODE||!ALLOWED_TAGS[node.nodeName]){return null;}var el=document.createElement(node.nodeName.toLowerCase());Array.from(node.attributes).forEach(function(attr){if(!ALLOWED_ATTRS[attr.name]){return;}if(attr.name==='src'){if(node.nodeName!=='IMG'||!isSafeIconSrc(attr.value)){return;}}el.setAttribute(attr.name,attr.value);});Array.from(node.childNodes).forEach(function(child){var safe=sanitizeNode(child);if(safe){el.appendChild(safe);}});return el;}try{var doc=(new window.DOMParser()).parseFromString('<div>'+iconhtml+'</div>','text/html');var root=doc.body.firstChild;if(!root){return;}Array.from(root.childNodes).forEach(function(child){var safe=sanitizeNode(child);if(safe){target.appendChild(safe);}});}catch(e){target.textContent=target.textContent||'';}} function getCurrentVideoTime(){return state.lasttime||0;} function installNotesToggle(){var btn=document.getElementById('videotrack-notes-toggle');var body=document.getElementById('videotrack-notes-body');if(!btn||!body){return;}var KEY='videotrack_notes_collapsed_'+(config.cmid?String(config.cmid):'x');function setCollapsed(collapsed){body.style.display=collapsed?'none':'';btn.setAttribute('aria-expanded',collapsed?'false':'true');btn.textContent=collapsed?(config.noteshowlabel||'Show notes'):(config.noteshidelabel||'Hide notes');try{window.sessionStorage.setItem(KEY,collapsed?'1':'0');}catch(e){}} var saved=null;try{saved=window.sessionStorage.getItem(KEY);}catch(e){}setCollapsed(saved==='1');btn.addEventListener('click',function(){var isCollapsed=btn.getAttribute('aria-expanded')==='false';setCollapsed(!isCollapsed);});} function installNoteHandler(){if(!config.studentnotesenabled){return;}var saveBtn=document.getElementById('videotrack-note-save');var textarea=document.getElementById('videotrack-note-input');if(!saveBtn||!textarea){return;} function setNoteButtonState(playing){if(!saveBtn){return;}saveBtn.setAttribute('aria-disabled',playing?'false':'true');saveBtn.classList.toggle('videotrack-note-save-disabled',!playing);} document.addEventListener('videotrack:playstate',function(e){setNoteButtonState(e.detail&&e.detail.playing);}); function appendNoteRow(noteid,videotime,text){var list=document.getElementById('videotrack-notes-list');if(!list){return;}var li=document.createElement('li');li.className='videotrack-note-item';li.dataset.noteid=noteid; var timeSpan=document.createElement('span');timeSpan.className='videotrack-note-time text-muted me-1 small';timeSpan.textContent=formatSeconds(videotime);li.appendChild(timeSpan); var textSpan=document.createElement('span');textSpan.className='videotrack-note-text';textSpan.textContent=text;li.appendChild(textSpan); var delBtn=document.createElement('button');delBtn.type='button';delBtn.className='btn btn-link btn-sm videotrack-delete-note ms-1';delBtn.dataset.noteid=noteid;delBtn.textContent=config.removenotelabel||'Remove note';li.appendChild(delBtn);list.appendChild(li);} saveBtn.addEventListener('click',function(){if(saveBtn.getAttribute('aria-disabled')==='true'){return;}var text=textarea.value.trim();if(!text){textarea.focus();return;} var currentTime=getCurrentVideoTime(); saveBtn.setAttribute('aria-disabled','true');saveBtn.classList.add('videotrack-note-save-saving');saveCurrentProgress('note').then(function(){return ajax('mod_videotrack_save_note',{cmid:config.cmid,sessionid:state.sessionid,videotime:currentTime,notetext:text,playbackrate:state.playbackrate||1,});}).then(function(response){saveBtn.classList.remove('videotrack-note-save-saving'); setNoteButtonState(state.playing);if(response&&response.noteeventid){appendNoteRow(response.noteeventid,currentTime,text);textarea.value=''; var panel=document.getElementById('videotrack-notes-panel');var hint=panel?panel.querySelector('.videotrack-note-charcount'):null;if(hint){hint.textContent='2000 '+(config.charsremaininglabel||'chars remaining');}textarea.focus();}}).catch(function(){saveBtn.classList.remove('videotrack-note-save-saving'); setNoteButtonState(state.playing); var statusEl=document.getElementById('videotrack-status-msg');if(statusEl){statusEl.setAttribute('role','alert');statusEl.textContent=config.noteerrorlabel||'Could not save note. Please try again.';window.setTimeout(function(){statusEl.textContent='';},4000);}});}); document.addEventListener('click',function(e){var delBtn=e.target.closest('.videotrack-delete-note');if(!delBtn){return;}var noteid=parseInt(delBtn.dataset.noteid,10);if(!noteid){return;} ajax('mod_videotrack_delete_reaction',{cmid:config.cmid,reactioneventid:noteid,}).then(function(response){if(response&&response.deleted){var li=delBtn.closest('li');if(li){var list=li.parentElement;li.remove(); var next=list?list.querySelector('.videotrack-note-item button'):null;if(next){next.focus();}else if(textarea){textarea.focus();}}}}).catch(function(){});}); textarea.addEventListener('input',function(){var remaining=2000-textarea.value.length; var panel=document.getElementById('videotrack-notes-panel');var hint=panel?panel.querySelector('.videotrack-note-charcount'):null;if(hint){hint.textContent=remaining+' '+(config.charsremaininglabel||'chars remaining');}});} function installPosterHandler(){var overlay=document.getElementById('videotrack-poster-overlay');if(!overlay){return;} function removePoster(){if(overlay&&overlay.parentElement){overlay.style.opacity='0';window.setTimeout(function(){if(overlay&&overlay.parentElement){overlay.parentElement.removeChild(overlay);}},300);}}var playBtn=document.getElementById('videotrack-poster-play-btn');if(playBtn){playBtn.addEventListener('click',function(){removePoster(); if(player&&player.play){player.play().catch(function(){});}});} state._posterRemoved=false;document.addEventListener('videotrack:playstate',function onFirstPlay(e){if(e.detail&&e.detail.playing&&!state._posterRemoved){state._posterRemoved=true;removePoster();document.removeEventListener('videotrack:playstate',onFirstPlay);}});} return{init:function(initConfig){config=initConfig;HEARTBEAT_INTERVAL=(config.heartbeatinterval>0)?config.heartbeatinterval:30;state.sessionid=uuid();installGlobalListeners();installReactionHandler();installNoteHandler();installNotesToggle();installPosterHandler();loadVimeoSDK(buildPlayer);}};});
